const hasConflictingTunnelRouteV1 = `-- name: HasConflictingTunnelRouteV1 :one
SELECT EXISTS (
  SELECT 1
  FROM tunnel_routes
  WHERE tunnel_id = $1
    AND id <> $2
    AND desired_state = 'active'
    AND deleted_at IS NULL
    AND (
      match_type = $3
      OR (
        $3 IN ('managed', 'exact')
        AND match_type IN ('managed', 'exact')
      )
    )
    AND path_prefix IS NOT DISTINCT FROM $4
    AND match_hostname IS NOT DISTINCT FROM $5
    AND wildcard_suffix IS NOT DISTINCT FROM $6
) AS has_conflict
`

type HasConflictingTunnelRouteV1Params struct {
	TunnelID       string
	ExcludeID      string
	MatchType      string
	PathPrefix     sql.NullString
	MatchHostname  sql.NullString
	WildcardSuffix sql.NullString
}

func (q *Queries) HasConflictingTunnelRouteV1(ctx context.Context, arg HasConflictingTunnelRouteV1Params) (bool, error) {
	row := q.db.QueryRow(ctx, hasConflictingTunnelRouteV1,
		arg.TunnelID,
		arg.ExcludeID,
		arg.MatchType,
		arg.PathPrefix,
		arg.MatchHostname,
		arg.WildcardSuffix,
	)
	var has_conflict bool
	err := row.Scan(&has_conflict)
	return has_conflict, err
}

